import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        Set<Integer> aSet = new HashSet<>();
        for (int i = 0; i < n; i++) {
            aSet.add(sc.nextInt());
        }
        Set<Integer> bSet = new HashSet<>();
        for (int i = 0; i < m; i++) {
            bSet.add(sc.nextInt());
        }

        // Check for common digits
        int minCommon = Integer.MAX_VALUE;
        for (int d : aSet) {
            if (bSet.contains(d)) {
                minCommon = Math.min(minCommon, d);
            }
        }
        if (minCommon != Integer.MAX_VALUE) {
            System.out.println(minCommon);
            return;
        }

        // Find minimal two-digit number
        int minA = Integer.MAX_VALUE;
        for (int d : aSet) {
            minA = Math.min(minA, d);
        }
        int minB = Integer.MAX_VALUE;
        for (int d : bSet) {
            minB = Math.min(minB, d);
        }
        int candidate1 = minA * 10 + minB;
        int candidate2 = minB * 10 + minA;
        System.out.println(Math.min(candidate1, candidate2));
    }
}
